const developmentSupplements: Record<string, ReturnType<typeof l>> = {
  "practice-and-nonattachment": l("Un plan de estudio puede volver sobre estos dos términos a lo largo del curso y registrar cómo los interpretan distintas escuelas.", "A study plan can revisit these two terms throughout the course and record how different schools interpret them."),
  "what-is-yoga": l("Una definición clásica orienta una lectura particular, pero no es la única definición histórica ni la única forma legítima de práctica.", "A classical definition guides one particular reading, but it is neither the only historical definition nor the only legitimate form of practice."),
  "philosophy-sanskrit-glossary": l("Para leer la lista, empieza por separar escritura, transliteración y glosa: la forma devanagari conserva la escritura sánscrita; IAST permite representar sus sonidos con caracteres latinos; la guía entre paréntesis solo aproxima una pronunciación para hispanohablantes. Las vocales largas marcadas con macrón no son adornos y algunas consonantes tienen puntos que indican articulación retrofleja. No todos los acentos regionales suenan igual, y la recitación tradicional puede seguir reglas métricas que aquí no se enseñan. Usa las entradas para reconocer vocabulario, luego consulta diccionarios y fuentes del texto específico. Una glosa breve no resuelve debates de traducción: por ejemplo, dharma, yoga, nirodha y brahmacarya requieren contexto. Cuando prepares material docente, comprueba la ortografía con una fuente lingüística y conserva diacríticos, pues ayudan a distinguir palabras. La aproximación no pretende corregir ni reemplazar la enseñanza oral de personas competentes.", "Read each entry by separating script, transliteration, and gloss: Devanagari preserves Sanskrit writing; IAST represents its sounds in Latin characters; the parenthetical guide only approximates pronunciation for English speakers. Macron-marked long vowels are meaningful, and some dotted consonants indicate retroflex articulation. Regional accents differ, and traditional recitation may follow meter not taught here. Use entries to recognize vocabulary, then consult dictionaries and sources for the specific text. A brief gloss does not settle translation debates: dharma, yoga, nirodha, and brahmacarya require context. When preparing teaching materials, verify spelling with a linguistic reference and retain diacritics, which help distinguish words. The approximation does not aim to correct or replace oral teaching by competent speakers."),
};

export const philosophy = philosophyEntries.map((item) => ({
  ...item,
  fields: item.fields.map((entry) => {
    if (!("text" in entry)) return entry;
    if (entry.label.es === "Desarrollo" || entry.label.en === "Study" || item.id === "philosophy-sanskrit-glossary" && entry.label.es === "Uso del glosario") {
      const addition = developmentAddenda[item.id];
      const supplement = developmentSupplements[item.id];
      return addition ? { ...entry, text: l(`${entry.text.es} ${addition.es}${supplement ? ` ${supplement.es}` : ""}`, `${entry.text.en} ${addition.en}${supplement ? ` ${supplement.en}` : ""}`) } : entry;
    }
    if (["Reference", "Referencia", "Fuentes", "Lectura de referencia"].includes(entry.label.en) || ["Reference", "Referencia", "Fuentes", "Lectura de referencia"].includes(entry.label.es)) {
      const citation = bibliographies[item.id];
      return citation ? { ...entry, text: l(citation, citation) } : entry;
    }
    return entry;
  }),
}));






